ds = value
if not ds:	return []

# Buckets (x-axis)
buckets = ["0-7", "8-30", "31-60", "60+"]

# Group counts by maintenance type
data = {}

for row in ds:
	bucket = row["ageBucket"]
	mtype = row["maintenanceTypeName"] or "Unknown"

	if mtype not in data:
		data[mtype] = {b: 0 for b in buckets}

	if bucket in data[mtype]:
		data[mtype][bucket] += 1

# Convert to Apex series
series = []

for mtype, counts in data.items():
	series.append({
		"name": mtype,
		"type": "bar",
		"data": [counts[b] for b in buckets]
	})

return series

